const postback = input.postback || '';
const parts = postback.split('|');

// Handle special postbacks like CLEAR_CART
const isSpecialPostback = ['CLEAR_CART', 'VIEW_CART', 'CHECKOUT', 'REVIEW_MENU', 'MAIN_MENU', 'END_SESSION'].includes(postback);

// If it's a special postback, pass it through directly with the right flags
if (isSpecialPostback) {
  return {
    json: {
      ...input,
      isCompleteOrder: false,
      isBitesOrder: false
    }
  };
}

// Otherwise process as normal product selection
return {
  json: {
    ...input,
    isCompleteOrder: parts.length === 3 && parts[1] !== 'NONE',
    isBitesOrder: parts.length === 3 && parts[0].startsWith('BK-')
  }
};

